import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { MatSnackBar } from '@angular/material/snack-bar';
import { MatDialog } from '@angular/material/dialog';
import { ConfirmDialogComponent } from '../components/confirm-dialog/confirm-dialog.component';

export interface Notification {
  id: number;
  user: string;
  action: string;
  time: string;
  avatar: string;
  read: boolean;
  module?: string; // 'personas', 'denuncias', 'reportes', 'usuarios'
  type?: 'success' | 'error' | 'warning' | 'info';
}

@Injectable({
  providedIn: 'root'
})
export class NotificationService {
  private notificationsSubject = new BehaviorSubject<Notification[]>([]);
  notifications$ = this.notificationsSubject.asObservable();

  constructor(private snackBar: MatSnackBar, private config: MatSnackBar, private dialog: MatDialog ) {
    // Notificaciones de ejemplo (remover en producción)
    this.initializeSampleNotifications();
  }

  // ========== MÉTODOS PÚBLICOS ==========

  // Método para agregar notificaciones desde cualquier submódulo
 addNotification(notification: Omit<Notification, 'id' | 'read' | 'time'>): number {
  const id = Date.now();
  const timestamp = new Date().toISOString(); // Siempre usar timestamp real

  const newNotification: Notification = {
    ...notification,
    id,
    read: false,
    time: timestamp, // Siempre timestamp ISO
  };

  setTimeout(() => {
    const current = this.notificationsSubject.value;
    const updated = [newNotification, ...current].slice(0, 50);
    this.notificationsSubject.next(updated);
  }, 0);

  return id;
}

 showConfirm(
    title: string,
    message: string,
    onConfirm: () => void,
    onCancel?: () => void
  ): void {
    const dialogRef = this.dialog.open(ConfirmDialogComponent, {
      width: '400px',
      data: { title, message },
      disableClose: true
    });

    dialogRef.afterClosed().subscribe(result => {
      if (result === true) {
        onConfirm();
      } else if (onCancel) {
        onCancel();
      }
    });
  }

  // Método específico para módulo de personas
  addPersonaNotification(
    action: string,
    details?: string,
    type: 'success' | 'error' | 'warning' | 'info' = 'info',
    personaName?: string
  ): number {
    const fullAction = personaName
      ? `${action}: ${personaName}`
      : details
        ? `${action}: ${details}`
        : action;

    return this.addNotification({
      user: 'SIGPAZ',
      action: fullAction,
      avatar: '👤',
      module: 'personas',
      type: type
    });
  }

  // Método genérico para cualquier módulo
  addModuleNotification(
    module: string,
    action: string,
    details?: string,
    type: 'success' | 'error' | 'warning' | 'info' = 'info'
  ): number {
    const moduleNames: Record<string, string> = {
      'personas': 'Módulo Personas',
      'denuncias': 'Módulo Denuncias',
      'reportes': 'Módulo Reportes',
      'usuarios': 'Módulo Usuarios',
      'sistema': 'Sistema',
      'backup': 'Backup',
      'configuracion': 'Configuración'
    };

    const moduleTitle = moduleNames[module] || `Módulo ${module}`;
    const fullAction = details
      ? `${moduleTitle}: ${action} - ${details}`
      : `${moduleTitle}: ${action}`;

    return this.addNotification({
      user: 'SIGPAZ',
      action: fullAction,
      avatar: this.getModuleIcon(module),
      module,
      type
    });
  }

  // Método específico para denuncias (ya lo tenías)
  addDenunciaNotification(
    module: string,
    action: string,
    details?: string
  ): number {
    const messages: Record<string, string> = {
      'registro': `Denuncia registrada: ${details || 'Nueva entrada'}`,
      'seguimiento': `Actualización en seguimiento: ${details || 'Proceso actualizado'}`,
      'investigacion': `Investigación en progreso: ${details || 'Nueva evidencia'}`,
      'reportes': `Reporte generado: ${details || 'Documento listo'}`,
      'backup': `${action}: ${details || 'Operación completada'}`
    };

    return this.addNotification({
      user: 'SIGPAZ',
      action: messages[module] || action,
      avatar: this.getModuleIcon(module),
      module,
      type: 'info'
    });
  }

  // Métodos de gestión de notificaciones
  markAsRead(id: number): void {
    const current = this.notificationsSubject.value;
    const updated = current.map(notification =>
      notification.id === id ? { ...notification, read: true } : notification
    );
    this.notificationsSubject.next(updated);
  }

  markAllAsRead(): void {
    const current = this.notificationsSubject.value;
    const updated = current.map(notification => ({ ...notification, read: true }));
    this.notificationsSubject.next(updated);
  }

  clearAll(): void {
    this.notificationsSubject.next([]);
  }

  getUnreadCount(): Observable<number> {
    return this.notifications$.pipe(
      map(notifications => notifications.filter(n => !n.read).length)
    );
  }

  // ========== MÉTODOS DE TOAST/SnackBar ==========
  showSuccess(message: string, duration: number = 3000): void {
    this.snackBar.open(message, 'Cerrar', {
      duration,
      panelClass: ['success-snackbar']
    });
    console.log('✅ ' + message);
  }

  showError(message: string, duration: number = 5000): void {
    this.snackBar.open(message, 'Cerrar', {
      duration,
      panelClass: ['error-snackbar']
    });
    console.error('❌ ' + message);
  }

  showInfo(message: string, duration: number = 3000): void {
    this.snackBar.open(message, 'Cerrar', {
      duration,
      panelClass: ['info-snackbar']
    });
    console.info('ℹ️ ' + message);
  }

  showWarning(message: string, duration: number = 4000): void {
    this.snackBar.open(message, 'Cerrar', {
      duration,
      panelClass: ['warning-snackbar']
    });
    console.warn('⚠️ ' + message);
  }

  // ========== MÉTODOS PRIVADOS ==========
  private initializeSampleNotifications(): void {
    const sampleNotifications: Notification[] = [
      // Puedes agregar notificaciones de ejemplo aquí si quieres
      // {
      //   id: 1,
      //   user: 'Sistema',
      //   action: 'Bienvenido al sistema SIGPAZ',
      //   time: 'Ahora',
      //   avatar: '👋',
      //   read: false,
      //   module: 'sistema',
      //   type: 'info'
      // }
    ];

    this.notificationsSubject.next(sampleNotifications);
  }

  private getModuleIcon(module: string): string {
    const icons: Record<string, string> = {
      'personas': '👤',
      'denuncias': '📋',
      'registro': '📝',
      'seguimiento': '🔍',
      'investigacion': '⚖️',
      'reportes': '📊',
      'backup': '💾',
      'usuarios': '👥',
      'sistema': '⚙️',
      'configuracion': '⚙️'
    };
    return icons[module] || '💡';
  }



 success(message: string, action: string = 'Cerrar'): void {
    this.snackBar.open(message, action, {
      ...this.config,
      panelClass: ['success-snackbar']
    });
  }

  error(message: string, action: string = 'Cerrar'): void {
    this.snackBar.open(message, action, {
      ...this.config,
      panelClass: ['error-snackbar'],
      duration: 7000
    });
  }

  warning(message: string, action: string = 'Cerrar'): void {
    this.snackBar.open(message, action, {
      ...this.config,
      panelClass: ['warning-snackbar'],
      duration: 6000
    });
  }

  info(message: string, action: string = 'Cerrar'): void {
    this.snackBar.open(message, action, {
      ...this.config,
      panelClass: ['info-snackbar']
    });
  }

}
