import { Injectable } from '@angular/core';
import { CatalogoFormData } from '../models/catalogo-form.model';
import { CatalogoEntityType } from '../models/catalogo-entity.model';

@Injectable({ providedIn: 'root' })
export class CatalogosValidationService {

 validarFormulario(entityType: CatalogoEntityType, data: CatalogoFormData): { isValid: boolean; errors: string[] } {
  const errors: string[] = [];

  // ✅ Obtener el nombre de forma más flexible
  const nombre = data.nombre || data.nombre_cargo || '';

  if (!nombre || nombre.trim().length < 2) {
    errors.push(`El nombre debe tener al menos 2 caracteres`);
  }

  // ✅ La descripción es OPCIONAL, no obligatoria
  // Solo validar si se proporciona y es menor a 2 caracteres
  if (data.descripcion && data.descripcion.trim().length > 0 && data.descripcion.trim().length < 2) {
    errors.push('La descripción debe tener al menos 2 caracteres si se proporciona');
  }

  return { isValid: errors.length === 0, errors };
}

  validarEliminacionFisica(confirmacionTexto: string): { isValid: boolean; error?: string } {
    if (confirmacionTexto !== 'ELIMINAR') {
      return { isValid: false, error: 'Debe escribir exactamente "ELIMINAR" para confirmar' };
    }
    return { isValid: true };
  }
}
