import { Component, OnInit, OnDestroy, ChangeDetectorRef, ViewEncapsulation } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterModule } from '@angular/router';
import { Subject, takeUntil, finalize } from 'rxjs';
import { trigger, transition, style, animate } from '@angular/animations';

// Componentes
import { HelpSupportComponent } from '../../../dashboard/components/help-support/help-support.component';
import { MenuComponent } from '../../../../layouts/menu/menu.component';
import { HeaderComponent } from '../../../../layouts/header/header.component';
import { FooterComponent } from '../../../../layouts/footer/footer.component';

// Servicios
import { CatalogosStateService } from '../../services/catalogos-state.service';
import { CatalogosCrudService } from '../../services/catalogos-crud.service';
import { CatalogosPaginationService } from '../../services/catalogos-pagination.service';
import { CatalogosValidationService } from '../../services/catalogos-validation.service';
import { CatalogoService } from '../../../../services/catalogo.service';
import { NotificationService } from '../../../../shared/services/notificationold.service';
import { LoadingService } from '../../../../core/services/loading.service';
import { AuthService } from '../../../../core/services/auth.service';
import { ThemeService, ThemeType } from '../../../../shared/features/home/services/theme.service';

// Models
import { CatalogoEntityType } from '../../models/catalogo-entity.model';
import { CatalogoFormData } from '../../models/catalogo-form.model';
import { CatalogoFilters } from '../../models/catalogo-filters.model';

// Constants
import { ENTIDADES_CATALOGOS, CONFIRMACION_ELIMINAR_FISICO } from '../../constants/catalogos.constants';

// Decorators
import { RequierePermisos } from '../../decorators/require-permissions.decorator';

// Pipes
import { FormatModelNamePipe } from '../../../../shared/pipes/format-model-name.pipe';

@Component({
  selector: 'app-catalogos',
  templateUrl: './catalogos.component.html',
  styleUrls: ['./catalogos.component.less'],
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    RouterModule,
    FormatModelNamePipe,
    HelpSupportComponent,
    MenuComponent,
    HeaderComponent,
    FooterComponent
  ],
  animations: [
    trigger('fadeIn', [
      transition(':enter', [
        style({ opacity: 0, transform: 'translateY(-10px)' }),
        animate('200ms ease-out', style({ opacity: 1, transform: 'translateY(0)' }))
      ]),
      transition(':leave', [
        animate('150ms ease-in', style({ opacity: 0, transform: 'translateY(-10px)' }))
      ])
    ])
  ]
})
export class CatalogosComponent implements OnInit, OnDestroy {
  // Constantes públicas para el template
  readonly ENTIDADES = ENTIDADES_CATALOGOS;
  readonly CONFIRMACION_ELIMINAR = CONFIRMACION_ELIMINAR_FISICO;

  // Estado del sidebar y tema
  isSidebarCollapsed = false;
  currentTheme: ThemeType = 'light';
showMinimizeNotification = false;
  // Estado del componente
  showHelpSupport = false;
  isMinimized = false;
  showModal = false;
  showDeleteModal = false;
  showConfirmacionFisicaModal = false;
  isEditing = false;
  currentEntityType: CatalogoEntityType | null = null;
  currentId: number | null = null;
isSearchOpen = false;
searchQuery = '';
searchResults: any[] = [];
cargandoDatos = false;
puedeVerCatalogos = true;
tipoUsuario = 'Usuario';
modalTitle = '';
  // Formulario
  formData: CatalogoFormData = { nombre: '', activo: true };
  // Confirmación eliminación física
  confirmacionTexto = '';
  nombreConfirmacion = '';

  // Datos de entidades
  tiposMedida: any[] = [];
  instituciones: any[] = [];
  estadosDenuncia: any[] = [];
  tiposConflicto: any[] = [];
  tiposNotificacion: any[] = [];
  estadosAsistencia: any[] = [];
  cargos: any[] = [];
  tiposDocumento: any[] = [];
  estadosCivil: any[] = [];
  sexos: any[] = [];
  tiposVinculo: any[] = [];

  // Permisos (por defecto false)
  puedeModificarCatalogos = false;

  private destroy$ = new Subject<void>();


  constructor(
    public router: Router,
    public catalogoService: CatalogoService,
    public notificationService: NotificationService,
    private stateService: CatalogosStateService,
    private crudService: CatalogosCrudService,
    private paginationService: CatalogosPaginationService,
    private validationService: CatalogosValidationService,
    private loadingService: LoadingService,
    private authService: AuthService,
    private themeService: ThemeService,
    private cdr: ChangeDetectorRef
  ) {}

  ngOnInit(): void {
    this.setupSubscriptions();
    this.setupTheme();
    this.loadInitialData();
    this.cargarPermisos();
  }

  ngOnDestroy(): void {
    this.destroy$.next();
    this.destroy$.complete();
  }

  private setupSubscriptions(): void {
    this.stateService.loading$
      .pipe(takeUntil(this.destroy$))
      .subscribe(loading => {
       if (loading) {
  this.loadingService.show();
} else {
  this.loadingService.hide();
}
      });
  }

  private setupTheme(): void {
    this.themeService.theme$
      .pipe(takeUntil(this.destroy$))
      .subscribe(theme => {
        this.currentTheme = theme;
      });
  }


  private loadInitialData(): void {
    this.loadingService.show('Cargando catálogos...');

    Promise.all([
      this.cargarTiposMedida(),
      this.cargarInstituciones(),
      this.cargarEstadosDenuncia(),
      this.cargarTiposConflicto(),
      this.cargarTiposNotificacion(),
      this.cargarEstadosAsistencia(),
      this.cargarCargos(),
      this.cargarTiposDocumento(),
      this.cargarEstadosCivil(),
      this.cargarSexos(),
      this.cargarTiposVinculo()
    ]).finally(() => {
      this.loadingService.hide();
    });
  }

  // Getters para el template
  get currentEntityName(): string {
    const entity = ENTIDADES_CATALOGOS.find(e => e.id === this.currentEntityType);
    return entity?.name || 'Registro';
  }

  get currentEntityData(): any[] {
    if (!this.currentEntityType) return [];

    const dataMap: Record<CatalogoEntityType, any[]> = {
      tipo_medida: this.tiposMedida,
      institucion: this.instituciones,
      estado_denuncia: this.estadosDenuncia,
      tipo_conflicto: this.tiposConflicto,
      tipo_notificacion: this.tiposNotificacion,
      estado_asistencia: this.estadosAsistencia,
      cargo: this.cargos,
      tipo_documento: this.tiposDocumento,
      estado_civil: this.estadosCivil,
      sexo: this.sexos,
      tipo_vinculo: this.tiposVinculo
    };

    return dataMap[this.currentEntityType] || [];
  }

  get currentFilters(): CatalogoFilters {
    return this.stateService['filtersSubject'].value;
  }

  get currentPage(): number {
    return this.stateService['currentPageSubject'].value;
  }

  get itemsPorPagina(): number {
    return this.paginationService.getItemsPorPagina();
  }

  get totalItems(): number {
    return this.filtrarItems(this.currentEntityData).length;
  }

  get totalPaginas(): number {
    return this.paginationService.getTotalPaginas(this.totalItems);
  }

  get registrosPaginados(): any[] {
    let items = this.filtrarItems(this.currentEntityData);
    return this.paginationService.paginar(items, this.currentPage);
  }

  get listarActivos(): any[] {
    return this.currentEntityData.filter(item => item.estado === true);
  }

  get listarInactivos(): any[] {
    return this.currentEntityData.filter(item => item.estado === false);
  }

  get haveEntitiesWithDescription(): boolean {
    return ['tipo_medida', 'institucion', 'tipo_conflicto', 'tipo_notificacion', 'cargo', 'tipo_documento', 'tipo_vinculo']
      .includes(this.currentEntityType || '');
  }

  // Métodos públicos
  seleccionarEntidad(entityType: CatalogoEntityType): void {
  this.currentEntityType = entityType;
    this.stateService.setEntityType(entityType);
    this.stateService.setFilters({ estado: 'todos' });
    this.loadingService.hide();
  }

  @RequierePermisos([1, 2])
  crearRegistro(): void {
    if (!this.currentEntityType) return;

    const validation = this.validationService.validarFormulario(this.currentEntityType, this.formData);
    if (!validation.isValid) {
      this.notificationService.warning('Validación', validation.errors.join(', '));
      return;
    }

    this.loadingService.show(`Creando ${this.currentEntityName}...`);

    this.crudService.crear(this.currentEntityType, this.formData)
      .pipe(finalize(() => this.loadingService.hide()))
      .subscribe({
        next: () => {
          this.notificationService.success('Éxito', `${this.currentEntityName} creado correctamente`);
          this.cerrarModal();
          this.recargarEntidadActual();
        },
        error: (error) => {
          this.notificationService.error('Error', error.error?.message || 'Error al crear el registro');
        }
      });
  }

private cargarPermisos(): void {
  this.puedeModificarCatalogos = this.catalogoService.puedeModificarCatalogos();
  this.puedeVerCatalogos = this.catalogoService.puedeVerCatalogos();
  this.tipoUsuario = this.catalogoService.getTipoUsuario() || 'Usuario';
}

  @RequierePermisos([1, 2])
  actualizarRegistro(): void {
    if (!this.currentEntityType || !this.currentId) return;

    const validation = this.validationService.validarFormulario(this.currentEntityType, this.formData);
    if (!validation.isValid) {
      this.notificationService.warning('Validación', validation.errors.join(', '));
      return;
    }

    this.loadingService.show(`Actualizando ${this.currentEntityName}...`);

    this.crudService.actualizar(this.currentEntityType, this.currentId, this.formData)
      .pipe(finalize(() => this.loadingService.hide()))
      .subscribe({
        next: () => {
          this.notificationService.success('Éxito', `${this.currentEntityName} actualizado correctamente`);
          this.cerrarModal();
          this.recargarEntidadActual();
        },
        error: (error) => {
          this.notificationService.error('Error', error.error?.message || 'Error al actualizar el registro');
        }
      });
  }

  eliminarRegistro(): void {
    if (!this.currentEntityType || !this.currentId) return;

    this.loadingService.show(`Desactivando ${this.currentEntityName}...`);

    this.crudService.eliminar(this.currentEntityType, this.currentId)
      .pipe(finalize(() => this.loadingService.hide()))
      .subscribe({
        next: () => {
          this.notificationService.success('Éxito', `${this.currentEntityName} desactivado correctamente`);
          this.cerrarDeleteModal();
          this.recargarEntidadActual();
        },
        error: (error) => {
          this.notificationService.error('Error', error.error?.message || 'Error al desactivar el registro');
        }
      });
  }

  abrirModalEliminarFisico(entityType: CatalogoEntityType, id: number): void {
    if (!this.puedeModificarCatalogos) {
      this.notificationService.error('Permisos insuficientes', 'No tiene permisos para eliminar registros');
      return;
    }

    const registro = this.obtenerPorId(id);
    this.currentEntityType = entityType;
    this.currentId = id;
    this.nombreConfirmacion = registro?.nombre || '';
    this.showDeleteModal = true;
  }

  abrirModalConfirmacionFisica(): void {
    this.confirmacionTexto = '';
    this.showConfirmacionFisicaModal = true;
    this.showDeleteModal = false;
  }

  ejecutarEliminacionFisica(): void {
    const validation = this.validationService.validarEliminacionFisica(this.confirmacionTexto);
    if (!validation.isValid) {
      this.notificationService.warning('Cancelado', validation.error!);
      return;
    }

    if (!this.currentEntityType || !this.currentId) return;

    this.loadingService.show('Eliminando registro...');
    this.showConfirmacionFisicaModal = false;

    this.crudService.eliminarFisico(this.currentEntityType, this.currentId, CONFIRMACION_ELIMINAR_FISICO)
      .pipe(finalize(() => this.loadingService.hide()))
      .subscribe({
        next: () => {
          this.notificationService.success('Éxito', `${this.currentEntityName} eliminado permanentemente`);
          this.cerrarDeleteModal();
          this.recargarEntidadActual();
        },
        error: (error) => {
          this.notificationService.error('Error', error.error?.message || 'Error al eliminar el registro');
          this.cerrarDeleteModal();
        }
      });
  }

  toggleEstado(id: number): void {
    if (!this.currentEntityType || !this.puedeModificarCatalogos) return;

    const registro = this.obtenerPorId(id);
    if (!registro) return;

    this.loadingService.show('Actualizando estado...');

    this.crudService.toggleEstado(this.currentEntityType, id, !registro.estado)
      .pipe(finalize(() => this.loadingService.hide()))
      .subscribe({
        next: () => {
          this.actualizarRegistroLocal(id, !registro.estado);
          this.notificationService.success('Éxito', `Registro ${!registro.estado ? 'activado' : 'desactivado'} correctamente`);
        },
        error: (error) => {
          this.notificationService.error('Error', error.error?.message || 'Error al cambiar el estado');
        }
      });
  }

  cambiarFiltro(tipo: 'todos' | 'activos' | 'inactivos'): void {
    this.stateService.setFilters({ estado: tipo });
  }

  cambiarPagina(pagina: number): void {
    this.stateService.setPage(pagina);
  }

  getPaginationArray(): (number | string)[] {
    return this.paginationService.getPaginationArray(this.currentPage, this.totalPaginas);
  }

  cerrarModal(): void {
    this.showModal = false;
    this.resetForm();
  }

  cerrarDeleteModal(): void {
    this.showDeleteModal = false;
    this.showConfirmacionFisicaModal = false;
    this.currentId = null;
    this.confirmacionTexto = '';
    this.nombreConfirmacion = '';
  }

  cerrarConfirmacionFisicaModal(): void {
    this.showConfirmacionFisicaModal = false;
    this.confirmacionTexto = '';
  }

  resetForm(): void {
    this.formData = { nombre: '', activo: true };
    this.currentId = null;
    this.isEditing = false;
  }

  recargarEntidadActual(): void {
    this.loadInitialData();
  }

  // Métodos para el header
  onToggleSidebar(): void {
    this.isSidebarCollapsed = !this.isSidebarCollapsed;
  }

  onToggleHelpSupport(): void {
    this.showHelpSupport = !this.showHelpSupport;
  }

  minimizeToBubble(): void {
    this.isMinimized = true;
  }

  restoreFromBubble(): void {
    this.isMinimized = false;
  }

  closeBubble(event: MouseEvent): void {
    event.stopPropagation();
    this.showHelpSupport = false;
    this.isMinimized = false;
  }

  handleOverlayClick(event: MouseEvent): void {
    const target = event.target as HTMLElement;
    if (target.classList.contains('modal-overlay-sigpaz') && this.showHelpSupport && !this.isMinimized) {
      this.minimizeToBubble();
    }
  }

  // Métodos privados de carga de datos (similares a los originales pero manteniendo la estructura)
  private cargarTiposMedida(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getTiposMedida().subscribe({
        next: (data: any) => { this.tiposMedida = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarInstituciones(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getInstituciones().subscribe({
        next: (data: any) => { this.instituciones = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarEstadosDenuncia(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getEstadosDenuncia().subscribe({
        next: (data: any) => { this.estadosDenuncia = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarTiposConflicto(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getTiposConflicto().subscribe({
        next: (data: any) => { this.tiposConflicto = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarTiposNotificacion(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getTiposNotificacion().subscribe({
        next: (data: any) => { this.tiposNotificacion = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarEstadosAsistencia(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getEstadosAsistencia().subscribe({
        next: (data: any) => { this.estadosAsistencia = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarCargos(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getCargos().subscribe({
        next: (data: any) => { this.cargos = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarTiposDocumento(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getTiposDocumento().subscribe({
        next: (data: any) => { this.tiposDocumento = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarEstadosCivil(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getEstadosCiviles().subscribe({
        next: (data: any) => { this.estadosCivil = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarSexos(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getSexos().subscribe({
        next: (data: any) => { this.sexos = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private cargarTiposVinculo(): Promise<void> {
    return new Promise((resolve) => {
      this.catalogoService.getTiposVinculo().subscribe({
        next: (data: any) => { this.tiposVinculo = data; resolve(); },
        error: () => resolve()
      });
    });
  }

  private filtrarItems(items: any[]): any[] {
    const filters = this.currentFilters;

    if (filters.estado === 'activos') {
      return items.filter(item => item.estado === true);
    }
    if (filters.estado === 'inactivos') {
      return items.filter(item => item.estado === false);
    }
    return items;
  }

  private actualizarRegistroLocal(id: number, nuevoEstado: boolean): void {
    const updateItem = (items: any[]) => {
      const index = items.findIndex(item => this.getRegistroId(item) === id);
      if (index !== -1) {
        items[index] = { ...items[index], estado: nuevoEstado };
      }
      return [...items];
    };

    if (this.currentEntityType) {
      const dataMap: Record<CatalogoEntityType, any[]> = {
        tipo_medida: this.tiposMedida,
        institucion: this.instituciones,
        estado_denuncia: this.estadosDenuncia,
        tipo_conflicto: this.tiposConflicto,
        tipo_notificacion: this.tiposNotificacion,
        estado_asistencia: this.estadosAsistencia,
        cargo: this.cargos,
        tipo_documento: this.tiposDocumento,
        estado_civil: this.estadosCivil,
        sexo: this.sexos,
        tipo_vinculo: this.tiposVinculo
      };

      const items = dataMap[this.currentEntityType];
      if (items) {
        const updated = updateItem([...items]);
        dataMap[this.currentEntityType] = updated;
      }
    }
  }

  private obtenerPorId(id: number): any {
    return this.currentEntityData.find(item => this.getRegistroId(item) === id);
  }

 getEntityData(entityId: CatalogoEntityType): any[] {
  const dataMap: Record<CatalogoEntityType, any[]> = {
    tipo_medida: this.tiposMedida,
    institucion: this.instituciones,
    estado_denuncia: this.estadosDenuncia,
    tipo_conflicto: this.tiposConflicto,
    tipo_notificacion: this.tiposNotificacion,
    estado_asistencia: this.estadosAsistencia,
    cargo: this.cargos,
    tipo_documento: this.tiposDocumento,
    estado_civil: this.estadosCivil,
    sexo: this.sexos,
    tipo_vinculo: this.tiposVinculo
  };
  return dataMap[entityId] || [];
}



// Agrega estos métodos
onOpenSearchModal(): void {
  this.isSearchOpen = true;
}

closeSearchModal(): void {
  this.isSearchOpen = false;
  this.searchQuery = '';
  this.searchResults = [];
}

performSearch(): void {
  if (this.searchQuery.trim()) {
    this.searchResults = [
      { title: 'Configuraciones del Sistema', description: 'Gestionar configuraciones', icon: '⚙️' }
    ];
  }
}

clearSearch(): void {
  this.searchQuery = '';
  this.searchResults = [];
}

descargarReporte(): void {
  const reporte = JSON.stringify(this.currentEntityData, null, 2);
  const blob = new Blob([reporte], { type: 'application/json' });
  const url = window.URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `reporte_${this.currentEntityType}_${new Date().toISOString()}.json`;
  a.click();
  window.URL.revokeObjectURL(url);
  this.notificationService.success('Reporte generado', 'Reporte descargado exitosamente');
}

exportarExcel(): void {
  this.notificationService.info('Exportar Excel', 'Exportando a Excel...');
}

exportarPDF(): void {
  this.notificationService.info('Exportar PDF', 'Exportando a PDF...');
}

getEstadoClass(estado: boolean): string {
  return estado ? 'estado-activo' : 'estado-inactivo';
}

getEstadoText(estado: boolean): string {
  return estado ? 'Activo' : 'Inactivo';
}

getRegistroId(registro: any): number {
  if (!registro) return 0;

  const idFields = [
    `${this.currentEntityType}_id`,
    `id_${this.currentEntityType}`,
    `${this.currentEntityType?.replace('_', '')}_id`,
    'cargo_id',
    'genero_id',
    'id'
  ];

  for (const field of idFields) {
    if (registro[field] !== undefined && registro[field] !== null) {
      return Number(registro[field]);
    }
  }

  for (const key in registro) {
    if (key.toLowerCase().includes('id') && registro[key] !== undefined && registro[key] !== null) {
      return Number(registro[key]);
    }
  }

  return 0;
}

cambiarPaginaNumero(pagina: number | string): void {
  if (typeof pagina === 'number') {
    this.cambiarPagina(pagina);
  }
}

getNombreValue(): string {
  return this.currentEntityType === 'cargo' ? this.formData.nombre_cargo || '' : this.formData.nombre || '';
}

setNombreValue(value: string): void {
  if (this.currentEntityType === 'cargo') {
    this.formData.nombre_cargo = value;
  } else {
    this.formData.nombre = value;
  }
}

getNombreField(): string {
  return this.currentEntityType === 'cargo' ? 'nombre_cargo' : 'nombre';
}


abrirModalCrear(entityType: CatalogoEntityType): void {
  if (!this.puedeModificarCatalogos) {
    this.notificationService.error('Permisos insuficientes', 'No tiene permisos para crear registros');
    return;
  }

  this.currentEntityType = entityType;
  this.isEditing = false;
  this.modalTitle = `Nuevo ${this.currentEntityName}`;
  this.resetForm();
  this.showModal = true;
}

abrirModalEditar(entityType: CatalogoEntityType, id: number): void {
  if (!this.puedeModificarCatalogos) {
    this.notificationService.error('Permisos insuficientes', 'No tiene permisos para editar registros');
    return;
  }

  const registro = this.obtenerPorId(id);
  if (!registro) return;

  this.currentEntityType = entityType;
  this.currentId = id;
  this.isEditing = true;
  this.modalTitle = `Editar ${this.currentEntityName}`;
  this.formData = {
    nombre: registro.nombre || '',
    nombre_cargo: registro.nombre_cargo || '',
    descripcion: registro.descripcion || '',
    activo: registro.estado ?? registro.activo ?? true
  };
  this.showModal = true;
}
}
