import { Injectable } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class CatalogosPaginationService {
  private itemsPorPagina = 10;

  setItemsPorPagina(items: number): void {
    this.itemsPorPagina = items;
  }

  getItemsPorPagina(): number {
    return this.itemsPorPagina;
  }

  paginar<T>(items: T[], pagina: number, itemsPorPagina?: number): T[] {
    const limit = itemsPorPagina || this.itemsPorPagina;
    const start = (pagina - 1) * limit;
    return items.slice(start, start + limit);
  }

  getTotalPaginas(totalItems: number, itemsPorPagina?: number): number {
    const limit = itemsPorPagina || this.itemsPorPagina;
    return Math.ceil(totalItems / limit);
  }

  getPaginationArray(paginaActual: number, totalPaginas: number, delta: number = 2): (number | string)[] {
    const range: number[] = [];
    const rangeWithDots: (number | string)[] = [];

    for (let i = 1; i <= totalPaginas; i++) {
      if (i === 1 || i === totalPaginas || (i >= paginaActual - delta && i <= paginaActual + delta)) {
        range.push(i);
      }
    }

    let prev = 0;
    for (const i of range) {
      if (prev !== 0) {
        if (i - prev === 2) {
          rangeWithDots.push(prev + 1);
        } else if (i - prev !== 1) {
          rangeWithDots.push('...');
        }
      }
      rangeWithDots.push(i);
      prev = i;
    }

    return rangeWithDots;
  }
}
