import { Injectable } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';
import { CatalogoEntityType } from '../models/catalogo-entity.model';
import { CatalogoFilters } from '../models/catalogo-filters.model';

@Injectable({ providedIn: 'root' })
export class CatalogosStateService {
  private entityTypeSubject = new BehaviorSubject<CatalogoEntityType | null>(null);
  private loadingSubject = new BehaviorSubject<boolean>(false);
  private filtersSubject = new BehaviorSubject<CatalogoFilters>({ estado: 'todos' });
  private currentPageSubject = new BehaviorSubject<number>(1);

  entityType$ = this.entityTypeSubject.asObservable();
  loading$ = this.loadingSubject.asObservable();
  filters$ = this.filtersSubject.asObservable();
  currentPage$ = this.currentPageSubject.asObservable();

  setEntityType(type: CatalogoEntityType | null): void {
  this.entityTypeSubject.next(type);
}

  setLoading(loading: boolean): void {
    this.loadingSubject.next(loading);
  }

  setFilters(filters: Partial<CatalogoFilters>): void {
    this.filtersSubject.next({ ...this.filtersSubject.value, ...filters });
    this.resetPage();
  }

  setPage(page: number): void {
    this.currentPageSubject.next(page);
  }

  resetPage(): void {
    this.currentPageSubject.next(1);
  }

  getCurrentState() {
    return {
      entityType: this.entityTypeSubject.value,
      filters: this.filtersSubject.value,
      page: this.currentPageSubject.value
    };
  }

}
